// Generated by scripts/build-glossary-data.mjs from content-source/glossary. Do not edit by hand.
export const GLOSSARY_SHARD = Object.freeze({"fully-diluted-valuation":{"slug":"fully-diluted-valuation","cat":"basics","en":"Fully diluted valuation (FDV)","contentLocale":"zh-Hans","term":"完全稀释估值（FDV）","aka":["FDV","全流通市值","Fully diluted valuation"],"short":"完全稀释估值（FDV）是用当前价格乘以代币最大供应量（或总供应量）算出的估值，表示所有代币都流通后的理论市值。","body":[["很多新项目上线时只有一小部分代币在流通，其余分配给团队、投资人、生态基金，按计划在未来几年逐步解锁。只看",["流通市值","market-capitalization"],"会低估项目的真实估值，FDV 就是用来补上这一块的。"],"如果一个代币流通市值 2 亿美元、FDV 20 亿美元，说明目前只流通了 10%。未来另外 90% 进入市场时，若需求没有同步增长，价格就要承受稀释压力。所以“低流通、高 FDV”的代币是币圈经常讨论的风险点。",["不同数据网站计算 FDV 时，有的用最大供应量，有的用总供应量，对于没有上限的代币还会有差异。比较时最好用同一个数据源，并结合",["代币解锁","token-unlock"],"时间表一起看。"]],"example":["假设某新币价格 0.8 ",["USDT","usdt"],"，最大供应量 100 亿枚，目前流通 15 亿枚。流通市值 = 0.8 × 15 亿 = 12 亿 USDT，FDV = 0.8 × 100 亿 = 80 亿 USDT。如果一年后",["流通量","circulating-supply"],"增加到 30 亿枚而市值保持 12 亿 USDT 不变，价格就会被摊薄到 12 亿 ÷ 30 亿 = 0.4 USDT，跌一半。"],"mistakes":["只看流通市值觉得项目很小，忽视了庞大的 FDV。","以为 FDV 是未来价格目标，它只是按当前价格的理论计算。","不查解锁时间表，不知道哪天会有大量代币释放。"],"faq":[{"q":"FDV 高是坏事吗？","a":"不一定，但 FDV 远高于流通市值时，后续解锁会持续增加供应，需要更多买盘才能维持价格。"},{"q":"比特币的 FDV 怎么算？","a":"用比特币价格乘以 2100 万枚最大供应量。由于大部分比特币已经挖出，它的 FDV 与市值差距相对较小。"}],"title":"什么是 FDV？完全稀释估值的含义与计算","description":"FDV（完全稀释估值）是什么、怎么算、和流通市值有何不同，以及“低流通高 FDV”的代币为什么需要警惕解锁抛压。","related":[["market-capitalization","市值（Market Cap）","市值是一个加密货币的当前价格乘以流通量得到的总价值，用来比较不同币种的规模，英文为 Market Cap。"],["circulating-supply","流通量（Circulating Supply）","流通量是指当前已在市场上自由流通、可以被交易的代币数量，不包括仍处于锁仓或尚未发行的部分。"],["token-unlock","代币解锁（Token Unlock）","代币解锁是指原本锁仓、不能交易的代币按预定时间表释放进入流通，常见于团队、投资人和生态基金的份额。"],["tokenomics","代币经济学（Tokenomics）","代币经济学是指一个代币的供应量、分配比例、解锁节奏、用途和销毁机制等设计，决定了代币未来的供需结构。"]],"lesson":null,"coin":null,"tool":"/coins","cta":false},"mining":{"slug":"mining","cat":"basics","en":"Crypto mining","contentLocale":"zh-Hans","term":"挖矿（Crypto Mining）","aka":["Mining","矿工","矿池"],"short":"挖矿是在工作量证明区块链上用计算设备竞争打包区块、维护网络安全并获得新币奖励和手续费的过程。","body":[["矿工把待确认的交易打包成候选区块，然后反复计算",["哈希值","transaction-hash"],"，谁先找到符合难度要求的结果，谁就能把区块加到链上，并获得区块奖励和区块内的交易手续费。",["比特币","bitcoin"],"挖矿如今主要使用专用的 ASIC 矿机。"],["个人单独挖矿很难稳定出块，所以多数矿工加入矿池，把",["算力","hash-rate"],"集中起来，再按贡献分配收益。挖矿的主要成本是矿机、电费、散热和维护，收益则取决于币价、全网算力、难度和区块奖励。"],["挖矿只存在于 ",["PoW","proof-of-work"]," 链上，",["以太坊","ethereum"],"合并后已无法挖矿。各国对挖矿的电力、税收和合规要求不同，部分",["地区限制","geo-restrictions"],"或禁止挖矿。网上所谓“手机挖矿”“云挖矿高回报”很多是骗局，要先看清资金去向。"]],"example":"假设一台矿机每天能挖出约 0.0002 BTC，BTC 价格 60,000 USDT，日收入约 12 USDT。矿机功率 3.5 千瓦，一天耗电 84 度，电价 0.08 美元/度，电费约 6.7 美元。扣掉电费每天净赚约 5.3 USDT（按 1 USDT 约等于 1 美元计算）。若全网难度上升 20%，产量降到约 0.000167 BTC，净收益就只剩约 3.3 USDT。","mistakes":["只看矿机日收益，不算电费、难度上升和减半的影响。","相信承诺固定高收益的云挖矿平台，资金被卷走。","以为任何币都能挖，实际上 PoS 链没有挖矿。"],"faq":[{"q":"现在用电脑还能挖比特币吗？","a":"理论上可以，但普通电脑算力和 ASIC 矿机相差太大，电费远高于收益，实际上没有意义。"},{"q":"什么是矿池？","a":"矿池把许多矿工的算力集中起来一起挖，挖到区块后按每个人贡献的算力比例分配奖励，让收益更平稳。"}],"title":"什么是挖矿？加密货币挖矿的含义与成本","description":"加密货币挖矿是什么意思？讲清矿工如何出块获得奖励、矿池的作用、电费和难度如何影响收益，以及云挖矿骗局怎么识别。","related":[["proof-of-work","工作量证明（PoW）","工作量证明（PoW）是一种共识机制，矿工通过大量计算竞争求解哈希难题，最先找到答案的人获得出块权和奖励，比特币采用这种机制。"],["hash-rate","算力（Hash rate）","算力是矿机或整个工作量证明网络每秒能完成的哈希计算次数，常用TH/s、EH/s表示，全网算力越高，攻击网络所需的成本通常越高。"],["bitcoin-halving","比特币减半（Bitcoin Halving）","比特币减半是指每产出 21 万个区块（约四年）矿工的区块奖励自动减少一半的规则，2024 年 4 月减半后奖励降至 3.125 BTC。"],["blockchain","区块链（Blockchain）","区块链是一种由众多节点共同维护、按时间顺序把交易打包成区块并用密码学串联起来的公开账本，写入后极难篡改。"]],"lesson":null,"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":false},"validator":{"slug":"validator","cat":"basics","en":"Validator","contentLocale":"zh-Hans","term":"验证者（Validator）","aka":["Validator","验证节点"],"short":"验证者是权益证明区块链上质押代币、负责提议和验证新区块的节点运营者，正常工作获得奖励，违规会被罚没质押。","body":[["在 ",["PoS","proof-of-stake"]," 网络里，验证者取代了 ",["PoW","proof-of-work"]," 中矿工的角色。它们需要",["质押","staking"],"一定数量的",["原生币","coin-vs-token"],"，并保持",["节点","node"]," 24 小时在线。轮到自己时提议新区块，其他时候对别人提议的区块投票确认。",["以太坊","ethereum"],"上运行一个独立验证者通常需要质押 32 ETH。"],"验证者的收益来自协议奖励和一部分交易手续费。如果节点离线，会错过奖励甚至被小额扣罚；如果同时签署两个冲突的区块等严重违规，会被罚没（Slashing）部分质押并被强制退出。","大多数持币者不会自己当验证者，而是把代币委托给验证者，或通过交易所和流动性质押协议参与。选择时可以看验证者的在线率、佣金比例和过往是否被罚没过，不同链的委托规则差别较大。"],"example":"假设你把 1,000 枚某 PoS 代币委托给一个验证者，网络奖励年化约 7%，验证者收取 10% 佣金。全年毛奖励 1,000 × 7% = 70 枚，扣掉佣金 7 枚，你实际得到 63 枚，相当于 6.3%。如果这个验证者因违规被罚没 5%，你委托的代币也可能按比例受损，少掉约 50 枚。","mistakes":["只挑佣金最低的验证者，忽视了在线率和罚没记录。","以为委托后代币转给了验证者，其实多数链上委托不转移所有权，但会受罚没影响。","不了解解除委托的等待期，以为随时能取回。"],"faq":[{"q":"验证者和矿工有什么区别？","a":"矿工靠算力在 PoW 链上竞争出块，验证者靠质押代币在 PoS 链上被选中出块和投票，后者不需要高耗能矿机。"},{"q":"当以太坊验证者需要多少 ETH？","a":"独立运行一个以太坊验证者通常需要 32 ETH。不够的话，可以通过质押池、交易所或流动性质押协议参与。"}],"title":"什么是验证者（Validator）？含义与收益来源","description":"区块链验证者是什么？讲清验证者如何质押出块、奖励和罚没机制、佣金如何影响委托收益，以及选择验证者时要看什么。","related":[["proof-of-stake","权益证明（PoS）","权益证明（PoS）是一种共识机制，验证者通过质押代币获得出块和验证资格，作恶会被罚没质押，以太坊自 2022 年起采用。"],["staking","质押（Staking）","质押是把权益证明（PoS）区块链的代币锁定，用来支持网络验证并获得奖励的做法，你可以自己运行验证节点，也可以通过交易所或质押服务参与。"],["restaking","再质押（Restaking）","再质押是把已经质押的 ETH 或流动性质押凭证，再次用于为其他网络或服务提供安全保障，以换取额外奖励，同时承担额外罚没风险的做法。"],["blockchain","区块链（Blockchain）","区块链是一种由众多节点共同维护、按时间顺序把交易打包成区块并用密码学串联起来的公开账本，写入后极难篡改。"]],"lesson":null,"coin":{"slug":"ethereum","name":"Ethereum","symbol":"ETH"},"tool":null,"cta":false},"trading-pair":{"slug":"trading-pair","cat":"trading","en":"Trading pair","contentLocale":"zh-Hans","term":"交易对（Trading Pair）","aka":["Trading pair","币对"],"short":"交易对是指两种资产相互报价、可以直接兑换的组合，如 BTC/USDT 表示用 USDT 买卖 BTC，价格表示 1 个 BTC 值多少 USDT。","body":[["交易对由基础货币和计价货币组成，斜杠前是你要买卖的资产（基础货币），斜杠后是用来报价和支付的资产（计价货币）。在 ",["ETH","ethereum"],"/",["USDT","usdt"]," 中，买入就是用 USDT 换 ETH，卖出就是用 ETH 换回 USDT。"],["最常见的计价货币是 USDT、",["USDC","usdc"]," 等",["稳定币","stablecoin"],"，也有以 ",["BTC","bitcoin"],"、ETH 计价的交易对，比如 SOL/BTC。同一个币在不同交易对里的",["流动性","liquidity"],"可能差很多，通常 USDT 交易对成交最活跃、价差最小。"],"如果一个币没有你持有资产的直接交易对，就需要两步换：先把资产换成 USDT，再用 USDT 买目标币。每一步都有手续费和价差，选择流动性好的交易对能降低成本。"],"example":"假设你持有 0.1 BTC，想换成某个只有 USDT 交易对的代币。BTC/USDT 价格 65,000，你卖出 0.1 BTC 得到 6,500 USDT，扣 0.1% 手续费后约 6,493.5 USDT。再在 XYZ/USDT 以 2.5 USDT 买入，扣 0.1% 后得到约 2,594.8 枚。两步共付约 13 USDT 手续费。在 ETH/BTC 交易对中，0.05 的价格表示 1 ETH 值 0.05 BTC。","mistakes":["看反了交易对方向，把价格理解成 1 USDT 能买多少个币。","选了成交稀少的冷门交易对，导致价差和滑点很大。","不知道以 BTC 计价的交易对，赚了“币”却在 USDT 计价下亏损。"],"faq":[{"q":"BTC/USDT 是什么意思？","a":"表示用 USDT 给 BTC 报价，显示的价格就是 1 BTC 等于多少 USDT。买入用 USDT 支付，卖出得到 USDT。"},{"q":"为什么同一个币在不同交易对价格不同？","a":"因为计价货币不同，而且各交易对的供需和流动性独立，换算后通常接近，但会有小幅差异，套利者会拉近这些差距。"}],"title":"什么是交易对？BTC/USDT 的含义","description":"交易对是什么意思？讲清基础货币和计价货币、BTC/USDT 怎么读、为什么 USDT 交易对流动性最好，以及没有直接交易对时怎么换币。","related":[["spot-trading","现货交易（Spot Trading）","现货交易是以当前市场价格直接买卖加密货币并即时完成交割的交易方式，买入后你真正持有这个币。"],["order-book","订单簿（Order Book）","订单簿是交易所实时列出某个交易对所有未成交买单和卖单的列表，按价格排列，显示每个价位挂了多少数量。"],["liquidity","流动性（Liquidity）","流动性是指一个资产能否在不明显推动价格的情况下快速买入或卖出，流动性越好，买卖价差越窄、大额成交的滑点越小。"],["stablecoin","稳定币（Stablecoin）","稳定币是一种设计为与美元等法币或资产保持稳定兑换比例的加密货币，最常见的是 1 枚兑 1 美元的 USDT 和 USDC，是加密交易中的主要计价和结算工具。"]],"lesson":{"id":"E07","slug":"first-spot-trade","ep":7,"title":"第一笔现货：从100到0.002枚"},"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":true},"oco-order":{"slug":"oco-order","cat":"trading","en":"OCO order (one-cancels-the-other)","contentLocale":"zh-Hans","term":"OCO 订单（二选一订单）","aka":["OCO","One-Cancels-the-Other","二择一委托"],"short":"OCO 订单（One-Cancels-the-Other）是把两笔订单绑定在一起，其中一笔成交后另一笔自动撤销，常用于同时设置止盈和止损。","body":[["OCO 通常由一个",["限价单","limit-order"],"和一个止损（限价）单组成。以现货持仓为例：你在上方挂一个止盈限价卖单，在下方挂一个",["止损单","stop-loss"],"，价格先到哪个就执行哪个，另一个随即取消，避免两笔都成交导致卖超。"],"如果没有 OCO，你分别挂止盈和止损，就可能出现一笔成交后另一笔仍挂着的情况；在现货中，同一批币通常不能同时挂两笔卖单，资金会被冻结冲突。OCO 解决了这个问题。",["OCO 也能用于入场：比如在突破价上方挂一个买入止损单，在回调价下方挂一个限价买单，哪个先触发就按哪个入场。不同",["交易所","centralized-exchange"],"对 OCO 的支持范围不同，有的仅限现货，合约中通常直接提供止盈止损功能。"]],"example":["假设你持有 0.4 ",["ETH","ethereum"],"，买入价 2,000 ",["USDT","usdt"],"。你设置 OCO：止盈限价卖单 2,300，止损触发价 1,880、限价 1,870。如果价格先涨到 2,300，止盈成交，你盈利 (2,300 − 2,000) × 0.4 = 120 USDT，止损单自动撤销。如果价格先跌到 1,880，止损触发并在约 1,870 成交，亏损约 52 USDT，",["止盈单","take-profit"],"自动撤销。"],"mistakes":["把止损价和限价设置混淆，导致止损部分不成交。","以为 OCO 的两笔订单会同时成交。","在不支持 OCO 的市场里分别挂两笔单，结果一笔成交后忘了撤另一笔。"],"faq":[{"q":"OCO 是什么意思？","a":"OCO 是 One-Cancels-the-Other 的缩写，即“一个成交，另一个取消”，用来把两笔条件互斥的订单绑定在一起。"},{"q":"OCO 订单收手续费吗？","a":"只有实际成交的那笔会产生手续费，被取消的订单不收费，费率按成交时是挂单还是吃单计算。"}],"title":"什么是 OCO 订单？止盈止损二选一的用法","description":"OCO 订单是什么意思？讲清 OCO 如何把止盈和止损绑定、一笔成交后另一笔自动撤销的原理，以及现货中设置 OCO 的例子。","related":[["take-profit","止盈单（Take-Profit）","止盈单是预先设定目标价，当价格朝有利方向达到该价位时自动卖出（或平仓）锁定利润的订单。"],["stop-loss","止损单（Stop-Loss）","止损单是预先设定一个触发价，当价格不利地达到该价位时自动卖出（或平仓）以限制亏损的订单。"],["limit-order","限价单（Limit Order）","限价单是指定价格买入或卖出的订单，只在市场价格达到或优于你设定的价格时才成交，可能部分成交或一直不成交。"],["risk-reward-ratio","盈亏比（Risk-Reward Ratio）","盈亏比是一笔交易计划中可能亏损的金额与可能盈利的金额之比，例如止损亏 100、止盈赚 300，就是 1:3 的盈亏比。"]],"lesson":{"id":"E14","slug":"market-limit-cancel","ep":14,"title":"市价、限价、撤单，分别解决什么问题？"},"coin":null,"tool":null,"cta":false},"post-only-order":{"slug":"post-only-order","cat":"trading","en":"Post-only order","contentLocale":"zh-Hans","term":"只做挂单（Post-Only）","aka":["Post only","只做 Maker","被动委托"],"short":"只做挂单（Post-Only）是一种限价单选项，保证订单只以挂单（Maker）身份进入订单簿，如果会立即成交为吃单就自动取消或调整。","body":[[["交易所","centralized-exchange"],"一般对挂单收较低的费率，对吃单收较高费率，有的平台甚至对挂单给返佣。普通",["限价单","limit-order"],"如果价格设得“越过”了对手盘，就会立即成交成为吃单，付更高的费用。Post-Only 就是为了避免这种情况。"],["勾选 Post-Only 后，如果你的买价高于或等于当前卖一价，订单不会成交，而是被拒绝或取消（部分交易所会自动调整到不成交的价位）。这样你可以确保每笔成交都按",["挂单费","maker-taker-fees"],"率计算。"],["Post-Only 适合不急于成交、对手续费敏感的交易者，比如",["网格交易","grid-trading-bot"],"或高频挂单。缺点是行情快速移动时，你的订单可能反复被取消，错过成交。具体处理方式以交易所规则为准。"]],"example":["假设某交易所挂单费率 0.02%，吃单费率 0.05%。你每月合约成交额 200 万 ",["USDT","usdt"],"。如果全部是吃单，手续费 = 200 万 × 0.05% = 1,000 USDT；如果通过 Post-Only 全部按挂单成交，手续费 = 200 万 × 0.02% = 400 USDT，每月省下 600 USDT。代价是部分订单因价格变化被取消、需要重新挂。"],"mistakes":["以为勾了 Post-Only 订单就一定会成交。","在急需离场时用 Post-Only，结果订单被取消没能平仓。","不知道普通限价单也可能成为吃单，白白多付手续费。"],"faq":[{"q":"Post-Only 订单为什么被取消了？","a":"因为按你设定的价格会立即与对手盘成交，成为吃单。为保证只做挂单，交易所会拒绝或取消这笔订单。"},{"q":"Post-Only 只能用于限价单吗？","a":"是的。市价单必然是吃单，所以 Post-Only 只作为限价单的选项出现。"}],"title":"什么是只做挂单（Post-Only）？含义与用途","description":"Post-Only（只做挂单）是什么意思？讲清它如何保证订单按 Maker 费率成交、为什么订单会被取消，以及能节省多少手续费。","related":[["maker-taker-fees","挂单费与吃单费（Maker/Taker Fee）","挂单费与吃单费是交易所按订单角色收取的两档手续费：挂在订单簿上等待成交、提供流动性的一方付挂单费，立即与已有挂单成交的一方付吃单费。"],["limit-order","限价单（Limit Order）","限价单是指定价格买入或卖出的订单，只在市场价格达到或优于你设定的价格时才成交，可能部分成交或一直不成交。"],["time-in-force","订单有效期（GTC、IOC、FOK）","订单有效期（Time in Force）规定了一笔订单在未成交时保留多久以及如何处理未成交部分，常见选项有 GTC、IOC 和 FOK。"],["order-book","订单簿（Order Book）","订单簿是交易所实时列出某个交易对所有未成交买单和卖单的列表，按价格排列，显示每个价位挂了多少数量。"]],"lesson":{"id":"E14","slug":"market-limit-cancel","ep":14,"title":"市价、限价、撤单，分别解决什么问题？"},"coin":null,"tool":"/rates","cta":false},"maker-taker-fees":{"slug":"maker-taker-fees","cat":"trading","en":"Maker and taker fees","contentLocale":"zh-Hans","term":"挂单费与吃单费（Maker/Taker Fee）","aka":["挂单费","吃单费","Maker Taker 手续费","maker taker fee"],"short":"挂单费与吃单费是交易所按订单角色收取的两档手续费：挂在订单簿上等待成交、提供流动性的一方付挂单费，立即与已有挂单成交的一方付吃单费。","body":[[["订单簿","order-book"],"上的每一笔成交都有两方。先挂出",["限价单","limit-order"],"、在订单簿上排队等待的，叫挂单方（Maker），它给市场增加了可成交的深度；下单后立刻吃掉别人挂单的，叫吃单方（Taker），它消耗了深度。",["市价单","market-order"],"几乎一定是吃单，而价格没有立刻碰到对手盘的限价单通常是挂单。"],["为了鼓励更多人提供",["流动性","liquidity"],"，",["交易所","centralized-exchange"],"一般把挂单费定得比吃单费低，部分交易所的高等级 VIP 或",["做市商","market-maker"],"甚至能拿到负的挂单费，也就是返佣。具体费率因交易所、现货或合约、账户等级、是否使用平台币抵扣而不同，下单前应以交易所的费率页面为准。"],"对频繁交易的人来说，费率差会被成交次数放大。想确保自己按挂单成交，可以使用只做挂单（Post Only）选项：如果这笔限价单会立刻成交，系统会直接撤单，而不是让你按吃单费成交。"],"example":"假设某交易所合约挂单费率 0.02%，吃单费率 0.05%。你开一笔名义价值 10,000 USDT 的仓位：用限价单挂单成交付 2 USDT，用市价单吃单成交付 5 USDT。平仓时再付一次。如果你每月开平仓各 50 次，全部挂单的手续费约 200 USDT，全部吃单约 500 USDT，差额 300 USDT。","mistakes":["以为下了限价单就一定按挂单费计费，其实限价价格如果直接穿过对手盘，会立即成交并按吃单费收取。","只比较各交易所的挂单费，忽略自己实际大部分订单是市价单。","只看开仓手续费，忘了平仓、止损触发的市价单同样要付吃单费。"],"faq":[{"q":"挂单和吃单哪个手续费更低？","a":"大多数交易所挂单费低于吃单费，因为挂单为市场提供了流动性。少数高等级账户的挂单费率甚至为负，即成交后反而获得返还。"},{"q":"市价单是挂单还是吃单？","a":"市价单会立即与订单簿上的现有挂单成交，所以按吃单费计费。"},{"q":"怎样才能保证按挂单费成交？","a":"下单时勾选只做挂单（Post Only）。如果这笔单会立刻成交，系统会撤销它，从而保证只要成交就是挂单。"}],"title":"挂单费和吃单费是什么？Maker/Taker 手续费区别","description":"讲清挂单费（Maker）与吃单费（Taker）的区别、为什么挂单通常更便宜，以及如何用 Post Only 降低交易成本。","related":[["post-only-order","只做挂单（Post-Only）","只做挂单（Post-Only）是一种限价单选项，保证订单只以挂单（Maker）身份进入订单簿，如果会立即成交为吃单就自动取消或调整。"],["limit-order","限价单（Limit Order）","限价单是指定价格买入或卖出的订单，只在市场价格达到或优于你设定的价格时才成交，可能部分成交或一直不成交。"],["market-order","市价单（Market Order）","市价单是以当前市场上最优可得价格立即成交的订单，优点是成交快、几乎一定成交，缺点是无法控制成交价格。"],["vip-tier","VIP等级（VIP fee tier）","VIP等级是交易所根据用户过去一段时间的交易量或资产余额划分的手续费档位，等级越高，挂单和吃单手续费率通常越低，还可能获得更高的提币额度等权益。"],["referral-code","邀请码（返佣）","邀请码是交易所发给用户或合作方的推荐编号，新用户注册时填写后，双方可能获得手续费返佣、注册奖励等，具体权益由交易所的推荐计划规定。"]],"lesson":{"id":"E13","slug":"price-vs-fill-price","ep":13,"title":"屏幕上的价格，为什么不是我的成交价？"},"coin":null,"tool":"/rates","cta":true},"maintenance-margin":{"slug":"maintenance-margin","cat":"derivatives","en":"Maintenance margin","contentLocale":"zh-Hans","term":"维持保证金（Maintenance Margin）","aka":["维持保证金率","MMR","maintenance margin"],"short":"维持保证金是持有合约仓位所需的最低保证金，当仓位的保证金余额（含未实现盈亏）跌到这个水平时，交易所会触发强制平仓。","body":[["维持保证金 = 仓位价值 × 维持保证金率。维持保证金率通常远低于",["初始保证金","initial-margin"],"率，比如 0.5% 或 1%，并且随仓位规模增大而提高。具体数值因",["交易所","centralized-exchange"],"、币种和仓位档位而异，可以在合约的风险限额说明里查到。"],["开仓后，你的保证金余额会随着",["未实现盈亏","unrealized-pnl"],"变化。浮亏让余额不断下降，一旦低于维持保证金，就会被",["强平","liquidation"],"，也就是爆仓。强平判断一般使用",["标记价格","mark-price"],"，而不是",["最新成交价","last-price"],"。"],"维持保证金的存在，是为了让交易所在你的保证金完全亏光之前有时间平掉仓位，避免出现穿仓。所以实际强平价总比“保证金亏光”的价格更接近你的开仓价。"],"example":"假设你用 20 倍杠杆逐仓开了价值 50,000 USDT 的 BTC 多单，保证金 2,500 USDT，维持保证金率 0.5%，即需要至少 250 USDT。当浮亏达到 2,500 − 250 = 2,250 USDT 时就会被强平，对应价格下跌约 4.5%，而不是 5%。这还没算手续费，实际可承受的跌幅会再小一点。","mistakes":["以为保证金全部亏完才会强平，没算维持保证金。","不知道仓位越大维持保证金率越高，大仓位强平价比预想的更近。","用最新价而不是标记价格来估算离强平还有多远。"],"faq":[{"q":"维持保证金率是多少？","a":"因交易所、币种和仓位大小而不同，主流币小仓位常见在 0.4% 到 1% 左右，仓位越大越高，请查看交易所的风险限额表。"},{"q":"保证金低于维持保证金会马上爆仓吗？","a":"一般会立刻触发强平流程。部分交易所会在接近时先发风险提醒，或者在全仓模式下先尝试部分减仓。"}],"title":"维持保证金是什么？为什么它决定强平价","description":"解释维持保证金和维持保证金率的含义、它如何决定合约的强平价，以及为什么仓位越大、强平价离开仓价就越近。","related":[["initial-margin","初始保证金（Initial Margin）","初始保证金是开立一笔杠杆或合约仓位时必须冻结的最低资金，等于仓位价值除以杠杆倍数，杠杆越高，所需初始保证金越少。"],["liquidation-price","强平价（Liquidation Price）","强平价是标记价格达到后会触发仓位强制平仓的价格，由开仓价、杠杆倍数、维持保证金率以及保证金模式共同决定。"],["margin-call","追加保证金（Margin Call）","追加保证金是指仓位亏损使保证金接近维持要求时，交易所发出风险提醒，要求你补充保证金或减仓，否则仓位可能被强制平仓。"],["mark-price","标记价格（Mark Price）","标记价格是交易所用来计算未实现盈亏和判断强平的参考价格，通常以多家现货交易所的指数价格为基础，比最新成交价更难被短时操纵。"]],"lesson":{"id":"E20","slug":"maintenance-margin","ep":20,"title":"保证金为什么还没归零，就可能出局？"},"coin":null,"tool":"/liquidations","cta":false},"reduce-only-order":{"slug":"reduce-only-order","cat":"derivatives","en":"Reduce-only order","contentLocale":"zh-Hans","term":"只减仓（Reduce-Only）","aka":["只减仓订单","仅减仓","reduce only"],"short":"只减仓是合约下单时的一个选项，勾选后这笔订单只能减少或平掉现有仓位，绝不会开出新仓或让仓位反向。","body":[["在单向持仓模式下，卖出数量大于多单数量，多出来的部分会变成一张新空单。止盈",["止损单","stop-loss"],"、提前挂好的平仓单最容易出现这种问题：你手动平了一部分，原来挂的单数量没改，成交后就意外开了反向仓位。"],["勾选只减仓后，系统会把订单数量限制在当前持仓范围内。如果仓位已经全部平掉，这笔订单会被取消或无法成交，而不会开新仓。很多",["交易所","centralized-exchange"],"的止盈止损单默认就是只减仓。"],"只减仓也不会占用新的保证金，适合用来分批止盈和设置保护性止损。具体行为在双向持仓模式和单向持仓模式下略有不同，以交易所说明为准。"],"example":["假设你持有 0.5 ",["BTC","bitcoin"]," 多单，提前在 65,000 挂了一张卖出 1 BTC 的",["止盈单","take-profit"],"。没勾选只减仓时，价格到 65,000，卖单全部成交：0.5 BTC 平掉多单，另外 0.5 BTC 变成新的空单，价值约 32,500 ",["USDT","usdt"],"。勾选只减仓后，只会卖出 0.5 BTC 把多单平掉，剩下的数量自动取消。"],"mistakes":["手动平仓后忘了撤掉原来的止盈止损单，导致意外开出反向仓位。","挂平仓单时不勾选只减仓，数量填错就变成加仓或反手。","以为只减仓订单一定会成交，忽略它仍受限价和市场深度影响。"],"faq":[{"q":"只减仓有什么用？","a":"它保证订单只用来减少现有仓位，不会意外开新仓或反手，适合止盈止损和分批平仓。"},{"q":"仓位已经平掉，只减仓订单会怎样？","a":"通常会被系统自动取消或无法成交，不会开出新的仓位。"}],"title":"只减仓是什么意思？合约 Reduce-Only 用法","description":"解释合约下单中只减仓（Reduce-Only）选项的作用、为什么止盈止损单需要它，以及不勾选时可能意外开出反向仓位的情况。","related":[["take-profit","止盈单（Take-Profit）","止盈单是预先设定目标价，当价格朝有利方向达到该价位时自动卖出（或平仓）锁定利润的订单。"],["stop-loss","止损单（Stop-Loss）","止损单是预先设定一个触发价，当价格不利地达到该价位时自动卖出（或平仓）以限制亏损的订单。"],["perpetual-futures","永续合约（Perpetual Futures）","永续合约是一种没有到期日的期货合约，可以无限期持有，通过多空双方定期互付资金费率，让合约价格始终贴近现货价格。"],["long-and-short","做多与做空（Long and Short）","做多是预期价格上涨而买入或开多单，价格上涨时盈利；做空是预期价格下跌而卖出或开空单，价格下跌时盈利，两者是交易的两个基本方向。"]],"lesson":{"id":"E17","slug":"stop-loss-is-a-plan","ep":17,"title":"止盈止损，是计划，不是保险"},"coin":null,"tool":null,"cta":false},"wallet-address":{"slug":"wallet-address","cat":"wallets-security","en":"Wallet address","contentLocale":"zh-Hans","term":"钱包地址（Wallet Address）","aka":["钱包地址","充币地址","收款地址","Wallet address"],"short":"钱包地址是区块链上用于收款的一串字符，相当于你的收款账号，由公钥计算得出，可以公开给别人，但不同链的地址格式不同。","body":[["不同",["区块链","blockchain"],"的地址长得不一样：",["比特币","bitcoin"],"地址常以 1、3 或 bc1 开头；",["以太坊","ethereum"],"和 BNB 链等 EVM 链地址以 0x 开头，共 42 个字符；波场（TRON）地址以大写 T 开头。",["交易所","centralized-exchange"],"的“充币地址”就是平台为你在某条链上分配的收款地址。"],"地址格式相同不代表可以互转。比如同一个 0x 地址在以太坊、BNB 链、Arbitrum 上都能用，但你把币从以太坊发出，它只会出现在以太坊上，收款方如果只支持另一条链，就可能“到不了账”。","链上转账不可撤回，所以发送前要核对完整地址、选择的网络以及是否需要 Memo。复制粘贴后至少对照开头和结尾各 4 到 6 位，大额先小额测试。"],"example":["假设你要把 300 ",["USDT","usdt"]," 从交易所提到朋友的地址 0x5B2e……C41d。你粘贴后发现结尾变成了 C41b，说明剪贴板可能被恶意软件替换，或者复制错了。立刻停止操作，重新从朋友那里获取地址并逐位核对。如果没发现就提交，这 300 USDT 会转进一个你们都不控制的地址，无法追回。"],"mistakes":["只核对地址开头几位，忽略结尾，给地址投毒和剪贴板劫持留下机会。","从转账历史里直接复制旧地址，复制到的是诈骗者伪造的相似地址。","看到地址格式一样，就以为任意网络都能转过去。"],"faq":[{"q":"钱包地址可以公开吗？","a":"可以，地址就是用来收款的，公开不会导致资产被盗。但地址的余额和交易记录在区块浏览器上任何人都能查看。"},{"q":"转错地址能追回吗？","a":"链上交易无法撤回。如果是转到了交易所的其他用户或者可联系的人，可以尝试协商；转到无人控制或格式错误的地址，基本无法找回。"}],"title":"什么是钱包地址？充币地址的格式与核对方法","description":"钱包地址是什么？了解比特币、以太坊、波场等地址格式的差异，地址与网络的关系，以及转账前如何核对地址，避免转错无法追回。","related":[["blockchain-network","充提币网络（链的选择）","充提币网络是指充币或提币时选择的区块链，例如 USDT 可以走 TRC20、ERC20 或 BEP20 等不同网络，发送方和接收方必须选择同一条链。"],["memo-tag","Memo / 标签（Destination Tag）","Memo（也叫标签、Tag）是部分区块链转账时附带的一段数字或文字，交易所靠它识别充值属于哪个用户，充值时漏填或填错就可能无法自动到账。"],["address-poisoning","地址投毒（Address Poisoning）","地址投毒是一种诈骗手法，骗子生成一个首尾字符与你常用地址相同的假地址，向你发送小额或零额转账，让它混进你的交易记录，等你复制错地址。"],["withdrawal-whitelist","提币白名单（Withdrawal Whitelist）","提币白名单是交易所的一项安全设置，开启后账户只能向你事先登记并验证过的地址提币，即使账户被盗，对方也难以把资产转到陌生地址。"]],"lesson":{"id":"E09","slug":"pre-transfer-checklist","ep":9,"title":"转账之前，这几项一个也别猜"},"coin":null,"tool":null,"cta":false},"phishing":{"slug":"phishing","cat":"wallets-security","en":"Phishing","contentLocale":"zh-Hans","term":"钓鱼攻击（Phishing）","aka":["钓鱼","钓鱼网站","Phishing","钓鱼诈骗"],"short":"钓鱼攻击是指诈骗者冒充交易所、钱包或项目方，通过假网站、假邮件、假客服诱导你交出密码、验证码、助记词或签下恶意授权，从而盗取资产。","body":[["加密领域的钓鱼形式很多：搜索引擎广告里的仿冒官网、域名只差一个字母的网站、“账户异常”邮件、社交媒体上的假客服、",["空投","airdrop"],"领取页面、甚至被黑掉的项目官方账号发出的链接。"],["钓鱼的目标通常是三类东西：",["交易所","centralized-exchange"],"账号密码和 ",["2FA","two-factor-authentication"]," 码、钱包",["助记词","seed-phrase"],"或",["私钥","private-key"],"，以及链上的授权签名。第三类最隐蔽，你只是点了“确认”，就可能把代币的使用权交给了对方合约。"],"防范要点：官网只从书签或官方 App 进入；任何人索要助记词都是骗局；签名前看清钱包弹窗里的授权对象和额度；遇到“限时”“紧急”这类催促话术，先停下来核实。"],"example":["假设你在搜索结果第一条看到某交易所“官网”，域名把字母 l 换成了数字 1。你在上面输入账号、密码和 6 位 2FA 码，页面提示“系统维护”。实际上骗子在 30 秒内用这组信息登录了真正的交易所，把账户里的 1,200 ",["USDT","usdt"]," 提走。如果你从书签打开，或开启了提币白名单，就能挡住这次攻击。"],"mistakes":["通过搜索广告或群里分享的链接进入交易所官网。","相信私信你的“客服”，按指示提供验证码或远程控制手机。","在钱包弹窗里不看内容就点确认，签下了无限授权。"],"faq":[{"q":"怎么判断是不是钓鱼网站？","a":"逐字核对域名，从书签或官方 App 进入，留意防钓鱼码，凡是要求输入助记词的页面一律视为钓鱼。"},{"q":"点了钓鱼链接但没输入信息，有风险吗？","a":"只打开页面一般风险较低，但不要下载文件或连接钱包签名。若已签名或输入了信息，应立即修改密码、撤销授权并转移资产。"}],"title":"什么是钓鱼攻击？币圈常见钓鱼手法与防范","description":"加密货币钓鱼攻击是什么？了解假官网、假客服、假空投和恶意授权等常见手法，以及识别钓鱼网站、保护账户和钱包的实用做法。","related":[["anti-phishing-code","防钓鱼码（Anti-phishing Code）","防钓鱼码是你在交易所设置的一段自定义文字，之后平台发来的官方邮件里都会带上它，用来帮你分辨真假邮件，识别冒充交易所的钓鱼信息。"],["seed-phrase","助记词（Seed Phrase）","助记词是由 12 或 24 个英文单词组成的钱包备份，可以推导出钱包里的全部私钥，谁拿到助记词，谁就能控制这个钱包里的所有资产。"],["token-approval","代币授权（Token Approval）","代币授权是你在链上允许某个智能合约动用你钱包里指定代币的操作，授权额度决定合约最多能转走多少，常用于 DEX 交易和 DeFi 存款。"],["address-poisoning","地址投毒（Address Poisoning）","地址投毒是一种诈骗手法，骗子生成一个首尾字符与你常用地址相同的假地址，向你发送小额或零额转账，让它混进你的交易记录，等你复制错地址。"],["pig-butchering-scam","杀猪盘","杀猪盘是一种长期设局的诈骗，骗子先通过交友、恋爱或“带单”建立信任，再引导你在虚假平台投资加密货币，等你投入越来越多后卷款消失。"]],"lesson":{"id":"E04","slug":"find-the-official-exchange","ep":4,"title":"先认门，再注册：别把账户开在假平台"},"coin":null,"tool":null,"cta":false},"proof-of-reserves":{"slug":"proof-of-reserves","cat":"wallets-security","en":"Proof of reserves","contentLocale":"zh-Hans","term":"储备金证明（Proof of Reserves）","aka":["储备金证明","PoR","准备金证明","Proof of Reserves"],"short":"储备金证明（PoR）是交易所公开证明自己持有的用户资产储备至少等于用户存款总额的做法，通常结合默克尔树和链上地址来让用户自行核验。","body":[["2022 年 FTX 倒闭后，用户开始关心“",["交易所","centralized-exchange"],"里的币是否真的在”。不少交易所因此定期发布储备金证明：一方面公布其持有的链上地址及余额，另一方面用默克尔树把所有用户余额汇总，你可以用自己的记录验证账户余额是否被计入。"],"关键指标是储备率，即储备资产除以用户负债。储备率高于 100% 表示该币种的储备大于用户存款。各家交易所的公布频率、覆盖币种、是否有第三方审计都不同。","PoR 有局限：它是某个时间点的快照，可能只覆盖资产而没有完整反映负债，也无法证明这些资产没有被抵押或借出。它能提高透明度，但不能等同于全面审计。"],"example":["假设某交易所公布的 ",["BTC","bitcoin"]," 储备为 105,000 枚，用户 BTC 余额总和为 100,000 枚，储备率就是 105,000 除以 100,000，等于 105%。你在其验证页面输入自己的记录 ID，查到你的 0.3 BTC 余额已被纳入默克尔树，说明这次快照里你的资产被计入了负债总额。"],"mistakes":["看到储备率超过 100% 就认为交易所绝对安全，忽略了负债是否完整和快照时间点。","只看总储备金额，不看具体币种的储备率，部分小币可能低于 100%。","从不自己验证账户是否被计入，只相信宣传页面的数字。"],"faq":[{"q":"储备金证明可信吗？","a":"它比完全不公开要透明，但只是时间点快照，且负债一侧主要依赖交易所自报。结合第三方审计和长期的公开记录来判断更可靠。"},{"q":"怎么验证自己的资产在储备证明里？","a":"大多数交易所会在储备金证明页面提供验证工具，你可以用自己的账户哈希或记录 ID 查询是否被纳入默克尔树。"}],"title":"什么是储备金证明 PoR？交易所储备率怎么看","description":"储备金证明 PoR 是什么？了解交易所如何用链上地址和默克尔树公开储备、储备率怎么计算，以及 PoR 无法证明的局限性。","related":[["centralized-exchange","中心化交易所（CEX）","中心化交易所（CEX）是由公司运营、托管用户资产并撮合买卖订单的加密货币交易平台，如币安、OKX、Bybit、Bitget。"],["custodial-wallet","托管钱包（Custodial Wallet）","托管钱包是由交易所或其他第三方代为保管私钥的钱包，你通过账户密码登录使用，资产实际由平台控制，便捷但要承担平台风险。"],["insurance-fund","风险保障基金（Insurance Fund）","风险保障基金是合约交易所设立的资金池，用来弥补被强平仓位以差于破产价格成交时产生的穿仓损失，避免盈利方的收益受到影响。"],["on-chain-analysis","链上分析（On-chain analysis）","链上分析是通过研究区块链上公开记录的转账、地址余额、交易所资金流向等数据，来判断市场参与者行为和资金动向的分析方法。"]],"lesson":{"id":"E04","slug":"find-the-official-exchange","ep":4,"title":"先认门，再注册：别把账户开在假平台"},"coin":null,"tool":"/exchanges","cta":false},"crypto-earn":{"slug":"crypto-earn","cat":"exchange-features","en":"Crypto Earn (savings products)","contentLocale":"zh-Hans","term":"理财/赚币（Crypto Earn）","aka":["赚币","活期理财","定期理财","Simple Earn"],"short":"理财（赚币）是交易所提供的加密资产收益产品，把你账户里的闲置币放进活期或定期产品中，由平台通过借贷、质押或其他方式产生收益并按约定发放。","body":[["常见形式有两种：活期产品可以随时申购和赎回，收益率随市场变动；定期产品要锁定7天、30天或更长，期间不能提前取出或提前取出会损失收益，通常收益率更高。平台还会提供链上",["质押","staking"],"、",["双币投资","dual-investment"],"等结构更复杂的产品。"],["收益来源各不相同：",["稳定币","stablecoin"],"理财的收益多来自借给",["杠杆交易","margin-trading"],"者的利息，PoS代币的收益多来自质押奖励。页面上显示的年化可能是APR，也可能是APY，还可能包含限额内的活动加息，看清楚才能正确估算。"],"理财资产由平台托管，你承担的是平台本身的风险，包括经营和安全风险。不同产品的保本属性也不同，结构化产品可能让你以另一种资产结算。参与前看清产品说明中的收益来源、赎回规则和结算方式。"],"example":["假设你把5,000 USDT放进活期理财，年化APR为4%，按日计息，一年约得利息200 ",["USDT","usdt"],"，平均每天约0.55 USDT。如果改成30天定期，年化6%，到期利息为5,000 × 6% × 30 ÷ 365 ≈ 24.66 USDT，比活期同期约16.44 USDT多出约8.22 USDT，代价是这30天里资金不能随时取用。"],"mistakes":["把显示的高年化当成长期固定收益，没注意那只是限额内的活动利率。","把需要随时使用的资金放进定期产品，急用时无法赎回。","以为所有理财产品都保本，没看懂结构化产品的结算规则。"],"faq":[{"q":"交易所理财安全吗？","a":"资产由平台托管，你承担平台的经营和安全风险。选择储备公开透明、运营记录较好的平台，并避免把全部资产放在单一平台。"},{"q":"活期理财随时可以取出吗？","a":"大多数活期产品支持随时赎回，到账时间从即时到一两天不等，特殊行情下也可能有单日赎回额度限制，以产品说明为准。"}],"title":"什么是交易所理财（赚币）？活期与定期的区别","description":"交易所理财赚币是什么？了解活期和定期产品的区别、收益从哪里来、APR和APY怎么看，以及托管资产和结构化产品的风险。","related":[["staking","质押（Staking）","质押是把权益证明（PoS）区块链的代币锁定，用来支持网络验证并获得奖励的做法，你可以自己运行验证节点，也可以通过交易所或质押服务参与。"],["apr-vs-apy","APR 和 APY 的区别","APR 是不计复利的年化收益率，APY 是计入复利后的年化收益率；同一个利率下，复利频率越高，APY 就比 APR 高得越多。"],["dual-investment","双币投资（Dual investment）","双币投资是一种结构化理财产品：你选择目标价格和期限并获得较高的约定收益，到期时根据结算价与目标价的关系，用原币种或另一种币种连本带息结算。"],["custodial-wallet","托管钱包（Custodial Wallet）","托管钱包是由交易所或其他第三方代为保管私钥的钱包，你通过账户密码登录使用，资产实际由平台控制，便捷但要承担平台风险。"]],"lesson":null,"coin":null,"tool":"/activities","cta":true},"p2p-trading":{"slug":"p2p-trading","cat":"exchange-features","en":"P2P (C2C) trading","contentLocale":"zh-Hans","term":"P2P交易（C2C交易）","aka":["C2C","P2P","场外交易","OTC"],"short":"P2P交易（币圈常称C2C）是指用户之间在交易所提供的撮合平台上直接买卖加密资产，买方通过银行转账等方式付款给卖方，平台托管卖方的币作为担保。","body":["在P2P市场里，商家挂出广告，标明价格、限额和支持的付款方式。你下单后，卖方的币会被平台冻结托管；你按要求向卖方付款，卖方确认收款后放币，币就进入你的账户。如果对方不放币，你可以发起申诉，由平台客服介入。",["P2P是许多地区",["法币入金","fiat-on-ramp"],"和出金的主要通道，价格由商家自行报价，可能略高于或低于市场价。挑选商家时，可以看完成单数、完成率、平均放币时间和是否为认证商家。"],"主要风险来自付款环节：买到的币或收到的钱可能来自诈骗受害者，被称为“黑钱”，会导致你的银行卡被冻结。务必只在平台内沟通，付款人姓名要与订单实名一致，不要接受第三方代付，也不要在对方未付款时提前放币。各地对P2P交易的法律规定不同，使用前先了解当地政策。"],"example":["假设你想买1,000 ",["USDT","usdt"],"。商家甲报价7.20元，限额500至20,000元，完成率99%；商家乙报价7.25元。你选甲，需付7,200元，比乙省50元。下单后甲的1,000 USDT被平台冻结，你从本人名下的银行账户转账7,200元，点击“我已付款”。甲确认收款后放币，1,000 USDT进入你的账户。如果15分钟后对方仍不放币，你可以在订单页发起申诉。"],"mistakes":["按对方要求在平台外私下交易或转账，失去平台托管保障。","作为卖家时只看对方发来的付款截图就放币，没有确认款项真正到账。","接受与订单实名不一致的第三方付款，导致银行卡因涉案资金被冻结。"],"faq":[{"q":"P2P和C2C是一回事吗？","a":"在币圈基本是同一个意思，都指用户之间直接用法币买卖加密资产，只是不同交易所的叫法不同。"},{"q":"P2P交易怎么避免收到黑钱？","a":"选择完成率高的认证商家，付款和收款都使用本人实名账户，拒绝第三方代付，并保留订单和转账记录。"}],"title":"什么是P2P/C2C交易？流程与防骗要点","description":"P2P交易和C2C是什么意思？了解用户间法币买币的下单、托管、放币和申诉流程，以及如何避免黑钱冻卡和常见骗局。","related":[["fiat-on-ramp","法币入金通道（Fiat on-ramp）","法币入金通道是把美元、欧元、人民币等法定货币换成加密资产的渠道，例如银行转账、银行卡快捷买币、第三方支付和P2P（C2C）交易。"],["usdt","USDT（泰达币）","USDT（泰达币）是由 Tether 公司发行、设计为与美元 1:1 挂钩的稳定币，也是市值和交易量最大的稳定币之一，大多数交易所的现货和合约都以它计价。"],["pig-butchering-scam","杀猪盘","杀猪盘是一种长期设局的诈骗，骗子先通过交友、恋爱或“带单”建立信任，再引导你在虚假平台投资加密货币，等你投入越来越多后卷款消失。"],["kyc","KYC（了解你的客户）","KYC是“了解你的客户”（Know Your Customer）的缩写，指交易所等金融服务机构在开户或提高额度时核实用户真实身份的流程，通常需要证件和人脸识别。"]],"lesson":{"id":"E06","slug":"first-deposit-paths","ep":6,"title":"第一次入金：钱从哪里来，进到哪里去？"},"coin":null,"tool":null,"cta":true}});
